var WHY7={tp:'TP +5%',zaman:'zaman stopu (12 mum)',stop:'acil stop −25%','C50/80':'C 50/80 çıkışı','süre':'süre doldu (720 mum)','açık':'açık'};
function fp7(x){return !isFinite(x)?'—':x>=1000?x.toFixed(1):x>=1?x.toPrecision(5):x.toPrecision(4);}
function usd7(x){return isFinite(x)?(x>=0?'+$':'−$')+Math.abs(x).toFixed(2):'—';}
function tsi7(t){return new Date(t+3*36e5).toISOString().slice(0,16).replace('T',' ');}
function short7(s){return String(s).replace(/USDT$/,'');}
function findC7(sym){var a=ST.coins.concat(ST.bist);for(var i=0;i<a.length;i++)if(a[i].sym===sym)return a[i];return null;}

/* ---------- 1) ZAMAN MAKİNESİ ---------- */
var RP7={days:30,spd:10};
function rpTr(c){return ST.replay&&ST.replay.on&&c.trRp?c.trRp:(c.trades||[]);}
function rpTrades(days){var t0=Date.now()-days*DAY;
  ST.coins.forEach(function(c){if(!c.k4||!c.T||!c.s5)return;c.trRp=days<=30?c.trades:runTrades(c.k4,c.T.en,'time12',null,'yo6',c.sym,H4,t0).concat(runTrades(c.k1,c.s5,'C',c.J.pst,'loxx',c.sym,H1,t0));});
  ST.bist.forEach(function(c){if(!c.cr)return;c.trRp=days<=30?c.trades:runTrades(c.k1,c.cr,'tp5',null,'bist',c.sym,H1,t0);});}
replaySteps=function(){var src=ST.mode==='bist'?(ST.bist.filter(function(c){return c.sym==='THYAO';})[0]||ST.bist[0]):(ST.coins.filter(function(c){return c.sym==='BTCUSDT';})[0]||ST.coins[0]);if(!src)return [];
  var k=src.k1,t0=Date.now()-RP7.days*DAY,now=Date.now();return k.t.map(function(t){return t+H1;}).filter(function(t){return t>=t0&&t<=now;});};
var _rpStart7=rpStart;rpStart=function(){rpTrades(RP7.days);$('rpOut').innerHTML='';_rpStart7();var R=ST.replay;if(R&&R.on){R.speed=RP7.spd;rpSpdUi();document.body.classList.add('rpon7');}rpWinUi();};
var _rpLive7=rpLive;rpLive=function(){_rpLive7();$('rpOut').innerHTML='';document.body.classList.remove('rpon7');};
function rpLegs(){return ST.mode==='bist'?{bist:1}:{yo6:1,loxx:1};}
rpApply=function(force){var R=ST.replay;if(!R)return;var ix=Math.floor(R.x);R.T=R.steps[Math.min(R.steps.length-1,ix)];$('rpS').value=R.x;$('rpD').textContent=fmtT(R.T)+' TSİ · '+(ix+1)+'/'+R.steps.length;$('rpPlay').textContent=R.play?'❚❚':'▶';
  if(ix!==R.lastIdx||force){var prevT=R.lastIdx>=0?R.steps[R.lastIdx]:null;R.lastIdx=ix;pushFrame();
    if(prevT!=null&&R.T>prevT){var legs=rpLegs(),fired=[],done=[];LAY.dots.forEach(function(d,k){rpTr(d.c).forEach(function(t){if(!legs[t.leg])return;if(t.fireT>prevT&&t.fireT<=R.T)fired.push({k:k,t:t});if(!t.open&&t.exitT>prevT&&t.exitT<=R.T)done.push({k:k,t:t});});});
      var many=fired.length+done.length>8;fired.forEach(function(x){if(G.api&&G.mode==='3d')G.api.fire(x.k);rpLog(x);});
      fired.slice(-3).forEach(function(x){rpCard(x,'fire');});done.slice(many?-2:-4).forEach(function(x){rpCard(x,'done');});
      if(fired.length)sfx('chime');}}};
function rpCard(x,kind){var el=$('rpOut');if(!el)return;var t=x.t,b=short7(t.sym),s;
  if(kind==='fire')s='<div class="oc" style="--c:'+LEGC[t.leg]+'"><div class="h"><span><b>'+esc(b)+'</b> '+LEGN[t.leg]+' · <b class="g">✓ kesinleşti</b></span><span class="lb7">LAB · REPLAY</span></div>'+
     '<div>mum kapanışı '+fmtT(t.fireT)+' · giriş (sonraki açılış) <b>'+fp7(t.e)+'</b></div><small>'+(t.open?'sonuç: işlem bugün hâlâ açık':'sonuç '+fmtT(t.exitT)+' TSİ’de açılacak ▸ oynatmaya devam')+'</small></div>';
  else{var col=t.ret>0?'#38f5c0':'#ff4d6d';s='<div class="oc" style="--c:'+col+'"><div class="h"><span>◆ <b>SONUÇ</b> · <b>'+esc(b)+'</b> '+LEGN[t.leg]+'</span><span class="lb7">LAB · REPLAY</span></div>'+
     '<div class="res" style="color:'+col+'">'+esc(WHY7[t.why]||t.why||'çıkış')+' · '+pct(t.ret,2)+' · '+usd7(t.usd)+'</div>'+
     '<small>✓ kesinleşti '+fmtT(t.fireT)+' @'+fp7(t.e)+' → çıkış '+fmtT(t.exitT)+' · '+Math.round((t.exitT-t.fireT)/36e5)+' sa · MFE '+pct(t.mfe,1)+' · MAE '+pct(t.mae,1)+' · $10 × 2x, net maliyet</small></div>';}
  el.insertAdjacentHTML('afterbegin',s);while(el.children.length>2)el.removeChild(el.lastChild);}
var _rpLog7=rpLog;rpLog=function(x){_rpLog7(x);};
function rpJump(dir){var R=ST.replay;if(!R||!R.on){rpStart();R=ST.replay;if(!R)return;}var legs=rpLegs(),ts=[];LAY.dots.forEach(function(d){rpTr(d.c).forEach(function(t){if(legs[t.leg]&&t.fireT>=R.steps[0])ts.push(t.fireT);});});ts.sort(function(a,b){return a-b;});
  var cT=R.T,tg=null;if(dir>0){for(var i=0;i<ts.length;i++)if(ts[i]>cT){tg=ts[i];break;}}else{for(var j=ts.length-1;j>=0;j--)if(ts[j]<cT){tg=ts[j];break;}}if(tg==null)return false;rpGoto(tg);return true;}
function rpGoto(T){var R=ST.replay;if(!R)return;var ix=0;while(ix<R.steps.length-1&&R.steps[ix]<T)ix++;R.play=false;R.x=ix;R.lastIdx=Math.max(0,ix-1);if(ix===0)R.lastIdx=-1;rpApply(false);}
