function deepGo(){var m=/(?:^#|&)c=([^&]+)/.exec(location.hash);if(!m)return false;var w=findSym(decodeURIComponent(m[1]));if(!w){rtoast('Bağlantıdaki sembol bu evrende yok: '+decodeURIComponent(m[1]));return false;}V10.deep=w.c.sym;jumpTo(w);setTimeout(function(){window.scrollTo(0,0);var f=$('focus');if(f)f.scrollTop=0;},900);return true;}
function linkOf(c){return location.origin+location.pathname+location.search+'#c='+encodeURIComponent((c.b||c.sym).replace(/\.IS$/,''));}
